// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(uint256 seed) public {
        vm.assume(seed != 0);

        BankLikeHelper helper = new BankLikeHelper();

        address caller = address(helper);

        vm.prank(caller);
        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && c.tokenBalance(caller) == 20);
    }
}

contract BankLikeHelper {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
